{"status":"fulfilled","value":["evalsrc",{"chunk_id":"6005be","wall_time_seconds":0.00001327,"exit_code":0,"original_token_count":1519,"output":"#!/usr/bin/env python3
"""Choose a trigger threshold on validation only, then evaluate testing once."""

import argparse
import csv
import json
import wave
from pathlib import Path

import numpy as np

from microwakeword.audio.audio_utils import generate_features_for_clip
from microwakeword.inference import Model
from numpy.lib.stride_tricks import sliding_window_view


def load_pcm(path):
    with wave.open(str(path), "rb") as audio:
        pcm = audio.readframes(audio.getnframes())
    return np.frombuffer(pcm, dtype="<i2").copy()


def score_file(path, model_path, stride, smooth_frames, ignore_frames):
    samples = load_pcm(path)
    features = generate_features_for_clip(samples, step_ms=10)
    predictions = np.asarray(Model(str(model_path), stride=stride).predict_spectrogram(features))
    if len(predictions) < ignore_frames + smooth_frames:
        raise ValueError(f"Not enough inference frames for trigger policy: {path}")
    smoothed = sliding_window_view(predictions, smooth_frames).mean(axis=-1)
    return smoothed[ignore_frames:], len(samples) / 16000.0


def false_events(probabilities, threshold, cooldown_frames):
    cooldown = 0
    events = 0
    for probability in probabilities:
        cooldown = max(0, cooldown - 1)
        if cooldown == 0 and probability > threshold:
            events += 1
            cooldown = cooldown_frames
    return events


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--artifacts-dir", type=Path, required=True)
    parser.add_argument("--stride", type=int, default=3)
    parser.add_argument("--smooth-frames", type=int, default=5)
    parser.add_argument("--ignore-initial-frames", type=int, default=25)
    parser.add_argument("--cooldown-frames", type=int, default=25)
    parser.add_argument("--minimum-validation-recall", type=float, default=0.0)
    args = parser.parse_args()

    artifacts = args.artifacts_dir.resolve()
    model_path = artifacts / "trained_models/nihao_openvela/tflite_stream_state_internal_quant/stream_state_internal_quant.tflite"
    manifest = artifacts / "split_manifest.csv"
    if not model_path.is_file() or not manifest.is_file():
        raise SystemExit("Missing model or split manifest")
    with manifest.open(encoding="utf-8", newline="") as stream:
        records = list(csv.DictReader(stream))

    scored = {split: {label: [] for label in ("positive", "negative")}
              for split in ("validation", "testing")}
    durations = {split: 0.0 for split in scored}
    for row in records:
        if row["split"] not in scored:
            continue
        series, duration = score_file(
            Path(row["path"]), model_path, args.stride,
            args.smooth_frames, args.ignore_initial_frames,
        )
        scored[row["split"]][row["label"]].append(series)
        durations[row["split"]] += duration

    thresholds = np.arange(0.0, 1.001, 0.01)
    candidates = []
    for threshold in thresholds:
        false_count = sum(false_events(track, threshold, args.cooldown_frames)
                          for track in scored["validation"]["negative"])
        recall = sum(bool(np.any(track > threshold)) for track in scored["validation"]["positive"]) / len(scored["validation"]["positive"])
        if false_count == 0 and recall >= args.minimum_validation_recall:
            candidates.append((recall, threshold))
    if not candidates:
        raise SystemExit("No validation threshold meets the requested false-event and recall constraints")
    best_recall = max(recall for recall, _ in candidates)
    selected_threshold = min(threshold for recall, threshold in candidates if recall == best_recall)

    validation_false = sum(false_events(track, selected_threshold, args.cooldown_frames)
                           for track in scored["validation"]["negative"])
    validation_hits = sum(bool(np.any(track > selected_threshold)) for track in scored["validation"]["positive"])
    test_hits = sum(bool(np.any(track > selected_threshold)) for track in scored["testing"]["positive"])
    test_false = sum(false_events(track, selected_threshold, args.cooldown_frames)
                     for track in scored["testing"]["negative"])
    report = {
        "threshold_selection": "validation only: maximize positive recall with zero observed negative trigger events",
        "threshold": float(selected_threshold),
        "validation": {
            "positive_hits": testable_count(validation_hits, len(scored["validation"]["positive"])),
            "negative_false_trigger_events": int(validation_false),
            "duration_seconds": round(durations["validation"], 6),
        },
        "testing_once_at_frozen_threshold": {
            "positive_hits": testable_count(test_hits, len(scored["testing"]["positive"])),
            "negative_false_trigger_events": int(test_false),
            "negative_duration_seconds": round(sum(float(row["duration_seconds"]) for row in records if row["split"] == "testing" and row["label"] == "negative"), 6),
        },
        "trigger_policy": {
            "moving_average_frames": args.smooth_frames,
            "initial_frames_ignored": args.ignore_initial_frames,
            "cooldown_frames_after_trigger": args.cooldown_frames,
            "inference_stride_feature_frames": args.stride,
            "feature_step_ms": 10,
        },
        "limitations": [
            "single-speaker file-held-out personalized prototype",
            "does not establish cross-speaker or cross-session generalization",
            "very short negative duration; false-trigger counts are descriptive and cannot support a reliable per-hour rate",
        ],
    }
    out = artifacts / "threshold_evaluation.json"
    out.write_text(json.dumps(report, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(report, ensure_ascii=False, indent=2))
    print(f"Report: {out}")


def testable_count(count, total):
    return {"hits": int(count), "total": int(total), "recall": count / total if total else None}


if __name__ == "__main__":
    main()
"}]}

